/**
 * When index_number is supplied as an array, Excel evaluates the lookup
 * once for each value in the array, returning a result matrix which
 * mirrors the shape of the index_number argument.
 *
 * @param mixed $lookupValue
 * @param array $indexNumber
 */
protected static function evaluateIndexAsArray($lookupValue, array $lookupArray, array $indexNumber, bool $notExactMatch): array
{
    $result = [];
    foreach ($indexNumber as $row) {
        $rowElements = [];
        foreach (is_array($row) ? $row : [$row] as $index) {
            $rowElements[] = static::lookup($lookupValue, $lookupArray, $index, $notExactMatch);
        }
        $result[] = $rowElements;
    }

    return $result;
}

